/**
 * Módulo puro de wallet HD del exchange.
 *
 * Implementa, sin estado mutable ni I/O:
 *  - BIP-39: generación (CSPRNG, 256 bits => 24 palabras), normalización NFKD, validación
 *    (longitud / wordlist / checksum) y derivación de la seed binaria
 *    (PBKDF2-HMAC-SHA512, 2048 iteraciones, 64 bytes).            [HU-06-01 RN-1..RN-3, RN-7]
 *  - BIP-32: clave maestra y CKDpriv (hardened y normal) sobre secp256k1, con aritmética
 *    modular en BigInt.                                            [HU-06-02 RN-1, RN-3, RN-8]
 *  - BIP-44: path estándar de Ethereum `m/44'/60'/0'/0/address_index`
 *    (coin type 60, red Sepolia chainId 11155111).                 [HU-06-02 RN-2, RN-7, RN-9]
 *  - EIP-55: codificación con checksum de la dirección derivada de Keccak-256(X || Y).
 *                                                                  [HU-06-02 RN-4]
 *
 * CUSTODIA (HU-06-01 RN-5, HU-06-02 RN-6): este módulo nunca serializa, retorna ni logea el
 * mnemonic, la seed ni ninguna clave privada derivada. Los mensajes de error no contienen
 * material secreto (ni el mnemonic ni palabras suyas). Solo salen del módulo datos públicos:
 * la clave pública comprimida y la dirección.
 */

import { secp256k1 } from '@noble/curves/secp256k1';
import { hmac } from '@noble/hashes/hmac';
import { pbkdf2 as noblePbkdf2 } from '@noble/hashes/pbkdf2';
import { sha512 } from '@noble/hashes/sha512';
import { keccak_256 } from '@noble/hashes/sha3';
import {
  generateMnemonic as bip39GenerateMnemonic,
  validateMnemonic as bip39ValidateMnemonic,
} from '@scure/bip39';
import { wordlist as ENGLISH_WORDLIST } from '@scure/bip39/wordlists/english';
import { AppError, type ValidationIssue } from '../core/errors';

// ---------------------------------------------------------------------------
// Errores del módulo
// ---------------------------------------------------------------------------

/**
 * Mnemonic BIP-39 inválido: longitud distinta de 24 palabras, palabra fuera del wordlist
 * inglés o checksum incorrecto (HU-06-01 RN-2 => `VALIDATION_ERROR`).
 *
 * El mensaje NUNCA incluye el mnemonic ni ninguna de sus palabras (RN-5).
 */
export class MnemonicValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'MnemonicValidationError';
  }
}

/**
 * `address_index` fuera del espacio no-hardened `[0, 2^31 - 1]` (HU-06-02 RN-9).
 *
 * Es un error del catálogo (`VALIDATION_ERROR`, HTTP 422) con `details.issues` indicando el
 * parámetro `address_index`: si alcanza la superficie HTTP se serializa con el envelope
 * uniforme de HU-09-05, no como error interno.
 */
export class AddressIndexRangeError extends AppError {
  constructor(message: string) {
    const issues: ValidationIssue[] = [{ field: 'address_index', message }];
    super('VALIDATION_ERROR', message, { issues });
    this.name = 'AddressIndexRangeError';
  }
}

/**
 * No se pudo hallar un `address_index` con clave BIP-32 válida dentro del rango
 * no-hardened (HU-06-02 RN-8: `I_L >= n` o `k_hijo == 0`, probabilidad ~2^-127).
 */
export class DerivationExhaustedError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'DerivationExhaustedError';
  }
}

/**
 * Error interno (NO exportado) que señala la condición de borde de BIP-32 RN-8 en un paso
 * concreto de derivación. Se traduce a `DerivationExhaustedError` en la superficie pública.
 */
class InvalidChildKeyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'InvalidChildKeyError';
  }
}

// ---------------------------------------------------------------------------
// Constantes de dominio
// ---------------------------------------------------------------------------

/** Offset de los índices hardened de BIP-32: `0x80000000` = 2^31 (HU-06-02 RN-2). */
export const HARDENED_OFFSET = 0x80000000;

/** Último `address_index` válido del espacio no-hardened: 2^31 - 1 (HU-06-02 RN-9). */
export const MAX_ADDRESS_INDEX = HARDENED_OFFSET - 1;

/** Entropía fijada por el proyecto: 256 bits => 24 palabras (HU-06-01 RN-1). */
const MNEMONIC_ENTROPY_BITS = 256;

/** Cantidad de palabras exigida por el proyecto (HU-06-01 RN-1/RN-2 (a)). */
const MNEMONIC_WORD_COUNT = 24;

/** Orden del grupo de secp256k1 (`n`), HU-06-02 RN-1. */
const SECP256K1_N: bigint = BigInt(
  '0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141'
);

/** Componentes del path BIP-44 de Ethereum (HU-06-02 RN-2). */
const BIP44_PURPOSE = 44;
const BIP44_COIN_TYPE_ETHEREUM = 60; // SLIP-44 (00-fundaciones/activos-y-par-de-trading.md)
const BIP44_ACCOUNT = 0;
const BIP44_CHANGE = 0; // cadena externa, NO hardened

/** Clave HMAC de la derivación de la clave maestra BIP-32 (HU-06-02 RN-1). */
const BIP32_MASTER_KEY = 'Bitcoin seed';

/** Iteraciones y longitud del PBKDF2 de BIP-39 (HU-06-01 RN-3). */
const PBKDF2_ITERATIONS = 2048;
const SEED_BYTES = 64;

// ---------------------------------------------------------------------------
// Helpers de bytes / enteros (aritmética exacta con BigInt, nunca floats)
// ---------------------------------------------------------------------------

const utf8 = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, 'utf8'));

function bytesToHex(bytes: Uint8Array): string {
  let out = '';
  for (let i = 0; i < bytes.length; i++) out += bytes[i].toString(16).padStart(2, '0');
  return out;
}

function bytesToBigIntBE(bytes: Uint8Array): bigint {
  let n = 0n;
  for (let i = 0; i < bytes.length; i++) n = (n << 8n) | BigInt(bytes[i]);
  return n;
}

/** `ser256(k)`: entero de 256 bits en big-endian, 32 bytes (BIP-32). */
function ser256(value: bigint): Uint8Array {
  const out = new Uint8Array(32);
  let v = value;
  for (let i = 31; i >= 0; i--) {
    out[i] = Number(v & 0xffn);
    v >>= 8n;
  }
  return out;
}

/** `ser32(i)`: entero de 32 bits sin signo en big-endian, 4 bytes (BIP-32). */
function ser32(index: number): Uint8Array {
  const out = new Uint8Array(4);
  out[0] = (index >>> 24) & 0xff;
  out[1] = (index >>> 16) & 0xff;
  out[2] = (index >>> 8) & 0xff;
  out[3] = index & 0xff;
  return out;
}

function concatBytes(...parts: Uint8Array[]): Uint8Array {
  const total = parts.reduce((acc, p) => acc + p.length, 0);
  const out = new Uint8Array(total);
  let offset = 0;
  for (const p of parts) {
    out.set(p, offset);
    offset += p.length;
  }
  return out;
}

// ---------------------------------------------------------------------------
// BIP-39: mnemonic y seed
// ---------------------------------------------------------------------------

let wordSetCache: Set<string> | null = null;
function englishWordSet(): Set<string> {
  if (wordSetCache === null) wordSetCache = new Set<string>(ENGLISH_WORDLIST);
  return wordSetCache;
}

/**
 * Genera un mnemonic BIP-39 de 24 palabras (256 bits de entropía) usando el CSPRNG del
 * sistema (HU-06-01 RN-1). No se registra ni se retorna nada más: el llamador es responsable
 * de custodiarlo (RN-5/RN-6).
 */
export function generateMnemonic24(): string {
  return bip39GenerateMnemonic(ENGLISH_WORDLIST, MNEMONIC_ENTROPY_BITS);
}

/**
 * Normaliza el mnemonic a Unicode NFKD y colapsa los espacios en blanco a un único espacio
 * simple, recortando extremos (HU-06-01 RN-2). Para el wordlist inglés (ASCII puro) la NFKD
 * es un no-op, pero se aplica de forma genérica por conformidad con el estándar y robustez
 * ante mnemonics importados de sistemas con otra normalización.
 */
export function normalizeMnemonic(mnemonic: string): string {
  if (typeof mnemonic !== 'string') {
    throw new MnemonicValidationError('el mnemonic debe ser una cadena de texto');
  }
  return mnemonic.normalize('NFKD').trim().replace(/\s+/g, ' ');
}

/**
 * Valida el mnemonic conforme a HU-06-01 RN-2, en este orden:
 *   (a) longitud = exactamente 24 palabras (entropía fijada del proyecto: 256 bits);
 *   (b) todas las palabras pertenecen al wordlist BIP-39 inglés (2048 palabras);
 *   (c) checksum BIP-39 (últimos ENT/32 bits = primeros ENT/32 bits de SHA-256(entropía)).
 *
 * Lanza `MnemonicValidationError` (equivalente a `VALIDATION_ERROR`) sin incluir el mnemonic
 * ni ninguna palabra suya en el mensaje (RN-5).
 */
export function validateMnemonic24(mnemonic: string): void {
  const normalized = normalizeMnemonic(mnemonic);
  const words = normalized.length === 0 ? [] : normalized.split(' ');

  // (a) longitud
  if (words.length !== MNEMONIC_WORD_COUNT) {
    throw new MnemonicValidationError(
      `mnemonic inválido: se esperaban ${MNEMONIC_WORD_COUNT} palabras (256 bits de entropía) ` +
        `y se recibieron ${words.length}`
    );
  }

  // (b) wordlist
  const dictionary = englishWordSet();
  for (let i = 0; i < words.length; i++) {
    if (!dictionary.has(words[i])) {
      // Se reporta solo la POSICIÓN, nunca la palabra (custodia RN-5).
      throw new MnemonicValidationError(
        `mnemonic inválido: la palabra en la posición ${i + 1} no pertenece al wordlist BIP-39 inglés`
      );
    }
  }

  // (c) checksum
  if (!bip39ValidateMnemonic(normalized, ENGLISH_WORDLIST)) {
    throw new MnemonicValidationError('mnemonic inválido: el checksum BIP-39 no verifica');
  }
}

/**
 * Deriva la seed binaria de 512 bits (64 bytes) según HU-06-01 RN-3:
 * `PBKDF2(HMAC-SHA512, password = mnemonic_NFKD, salt = "mnemonic" + passphrase_NFKD,
 *  iteraciones = 2048, dkLen = 64)`.
 *
 * Función pura y determinista (RN-7). NO valida la longitud del mnemonic: es el algoritmo
 * puro de BIP-39, usado también con vectores canónicos de 12 palabras (HU-06-02). La
 * validación de provisioning es responsabilidad de `validateMnemonic24`.
 */
export function mnemonicToSeed(mnemonic: string, passphrase = ''): Buffer {
  const password = normalizeMnemonic(mnemonic);
  // La passphrase se normaliza NFKD pero NO se colapsan sus espacios: son significativos.
  const salt = 'mnemonic' + passphrase.normalize('NFKD');
  const derived = noblePbkdf2(sha512, utf8(password), utf8(salt), {
    c: PBKDF2_ITERATIONS,
    dkLen: SEED_BYTES,
  });
  return Buffer.from(derived);
}

// ---------------------------------------------------------------------------
// EIP-55 / dirección Ethereum
// ---------------------------------------------------------------------------

const ADDRESS_RE = /^0x[0-9a-fA-F]{40}$/;

/**
 * Codifica 20 bytes como dirección Ethereum con checksum EIP-55 (HU-06-02 RN-4).
 *
 * Acepta `Uint8Array`/`Buffer` de 20 bytes o un string hexadecimal de 40 dígitos, con o sin
 * prefijo `0x` y en cualquier caja. El algoritmo computa `Keccak-256` sobre la cadena ASCII
 * del hexadecimal en minúsculas (sin `0x`) y pasa a mayúscula el dígito `i` si el nibble `i`
 * del hash es >= 8.
 */
export function toChecksumAddress(address: string | Uint8Array): string {
  let lower: string;
  if (typeof address === 'string') {
    const raw = address.startsWith('0x') || address.startsWith('0X') ? address.slice(2) : address;
    if (!/^[0-9a-fA-F]{40}$/.test(raw)) {
      throw new Error('dirección inválida: se esperan 40 dígitos hexadecimales (20 bytes)');
    }
    lower = raw.toLowerCase();
  } else {
    if (!(address instanceof Uint8Array) || address.length !== 20) {
      throw new Error('dirección inválida: se esperan exactamente 20 bytes');
    }
    lower = bytesToHex(address);
  }

  const hash = keccak_256(utf8(lower));
  let out = '0x';
  for (let i = 0; i < lower.length; i++) {
    const ch = lower[i];
    // nibble i del hash: byte i>>1, mitad alta si i es par.
    const nibble = i % 2 === 0 ? hash[i >> 1] >> 4 : hash[i >> 1] & 0x0f;
    out += nibble >= 8 ? ch.toUpperCase() : ch;
  }
  return out;
}

/**
 * `true` si `address` es `0x` + 40 hex con checksum EIP-55 correcto.
 *
 * Nota deliberada sobre las formas sin caja mixta: una dirección **enteramente en minúsculas**
 * o **enteramente en mayúsculas** devuelve `false`, porque no transporta un checksum EIP-55
 * verificable (EIP-55 las considera "sin checksum"; que coincidan con la forma canónica sería
 * casualidad). Único caso en que esta regla no aplica: direcciones sin ningún dígito
 * alfabético (`a`-`f`), donde minúsculas y mayúsculas son la misma cadena y el checksum sí es
 * verificable de forma no ambigua; ahí se compara contra la forma canónica.
 */
export function isValidChecksumAddress(address: string): boolean {
  if (typeof address !== 'string' || !ADDRESS_RE.test(address)) return false;
  const body = address.slice(2);
  const hasCase = body.toLowerCase() !== body.toUpperCase();
  if (hasCase && (body === body.toLowerCase() || body === body.toUpperCase())) return false;
  return toChecksumAddress(body) === address;
}

// ---------------------------------------------------------------------------
// BIP-32 / BIP-44
// ---------------------------------------------------------------------------

/**
 * Punto de inyección para tests (AT-06-02-08): permite sustituir el HMAC-SHA512 usado por la
 * derivación BIP-32 para simular la condición de clave inválida (`I_L >= n` o `k_hijo == 0`,
 * probabilidad ~2^-127, no reproducible naturalmente).
 */
export interface DerivationDeps {
  hmacSha512?: (key: Uint8Array, data: Uint8Array) => Uint8Array;
}

const defaultHmacSha512 = (key: Uint8Array, data: Uint8Array): Uint8Array =>
  hmac(sha512, key, data);

/** Nodo extendido BIP-32 (privado). Nunca se expone fuera del módulo (RN-6). */
interface ExtendedKey {
  /** Clave privada como entero; permanece en memoria del módulo. */
  readonly k: bigint;
  readonly chainCode: Uint8Array;
}

/** `serP(point(k))`: clave pública comprimida (33 bytes) de la clave privada `k`. */
function compressedPublicKey(k: bigint): Uint8Array {
  return secp256k1.Point.BASE.multiply(k).toBytes(true);
}

/** Clave pública sin comprimir sin el prefijo `0x04`: `X || Y` (64 bytes). */
function uncompressedXY(k: bigint): Uint8Array {
  return secp256k1.Point.BASE.multiply(k).toBytes(false).subarray(1);
}

/**
 * Clave maestra BIP-32 (HU-06-02 RN-1):
 * `I = HMAC-SHA512("Bitcoin seed", seed)`, `k = I[0:32]`, `c = I[32:64]`, con `1 <= k < n`.
 */
function masterKeyFromSeed(seed: Uint8Array, hmacSha512: DerivationDeps['hmacSha512']): ExtendedKey {
  if (!(seed instanceof Uint8Array) || seed.length < 16 || seed.length > 64) {
    throw new Error('seed inválida: se esperan entre 16 y 64 bytes');
  }
  const I = (hmacSha512 ?? defaultHmacSha512)(utf8(BIP32_MASTER_KEY), seed);
  const k = bytesToBigIntBE(I.subarray(0, 32));
  if (k === 0n || k >= SECP256K1_N) {
    // BIP-32: seed inutilizable (probabilidad ~2^-127). No se filtra material secreto.
    throw new Error('BIP-32: la seed produce una clave maestra inválida (I_L fuera de [1, n-1])');
  }
  return { k, chainCode: I.subarray(32, 64) };
}

/**
 * `CKDpriv` de BIP-32 (HU-06-02 RN-3):
 *  - hardened (`i >= 2^31`): `I = HMAC-SHA512(c_par, 0x00 || ser256(k_par) || ser32(i))`
 *  - normal   (`i <  2^31`): `I = HMAC-SHA512(c_par, serP(point(k_par)) || ser32(i))`
 *  - `k_hijo = (I_L + k_par) mod n`, `c_hijo = I_R`.
 *
 * Si `I_L >= n` o `k_hijo == 0`, el índice es inválido (RN-8) y se lanza
 * `InvalidChildKeyError` para que el llamador avance al índice siguiente.
 */
function ckdPriv(
  parent: ExtendedKey,
  index: number,
  hmacSha512: DerivationDeps['hmacSha512']
): ExtendedKey {
  const data =
    index >= HARDENED_OFFSET
      ? concatBytes(new Uint8Array([0x00]), ser256(parent.k), ser32(index))
      : concatBytes(compressedPublicKey(parent.k), ser32(index));

  const I = (hmacSha512 ?? defaultHmacSha512)(parent.chainCode, data);
  const IL = bytesToBigIntBE(I.subarray(0, 32));
  if (IL >= SECP256K1_N) {
    throw new InvalidChildKeyError(`BIP-32: I_L >= n en el índice ${index}`);
  }
  const k = (IL + parent.k) % SECP256K1_N;
  if (k === 0n) {
    throw new InvalidChildKeyError(`BIP-32: k_hijo == 0 en el índice ${index}`);
  }
  return { k, chainCode: I.subarray(32, 64) };
}

/** Índice hardened: `value + 2^31` (HU-06-02 RN-2). */
function hardened(value: number): number {
  return value + HARDENED_OFFSET;
}

/**
 * Ruta BIP-44 de Ethereum para un `address_index`: `m/44'/60'/0'/0/${addressIndex}`
 * (HU-06-02 RN-2). Los índices efectivos de los componentes hardened son
 * 2147483692 (44'), 2147483708 (60') y 2147483648 (0'); `change` y `address_index` son
 * no-hardened.
 */
export function derivationPathFor(addressIndex: number): string {
  return `m/${BIP44_PURPOSE}'/${BIP44_COIN_TYPE_ETHEREUM}'/${BIP44_ACCOUNT}'/${BIP44_CHANGE}/${addressIndex}`;
}

/**
 * Nodo `m/44'/60'/0'/0` (la "cadena externa" de la cuenta 0), común a todos los índices.
 * Se calcula una sola vez por derivación / barrido de índices.
 */
function externalChainNode(seed: Uint8Array, hmacSha512: DerivationDeps['hmacSha512']): ExtendedKey {
  let node = masterKeyFromSeed(seed, hmacSha512);
  const path = [
    hardened(BIP44_PURPOSE), // 2147483692
    hardened(BIP44_COIN_TYPE_ETHEREUM), // 2147483708
    hardened(BIP44_ACCOUNT), // 2147483648
    BIP44_CHANGE, // 0 (no hardened)
  ];
  for (const index of path) node = ckdPriv(node, index, hmacSha512);
  return node;
}

/** Valida el rango no-hardened del `address_index` (HU-06-02 RN-9), ANTES de derivar. */
function assertAddressIndexInRange(addressIndex: number): void {
  if (
    typeof addressIndex !== 'number' ||
    !Number.isInteger(addressIndex) ||
    addressIndex < 0 ||
    addressIndex > MAX_ADDRESS_INDEX
  ) {
    throw new AddressIndexRangeError(
      `address_index inválido: debe ser un entero en [0, ${MAX_ADDRESS_INDEX}] ` +
        `(espacio no-hardened de BIP-32); se recibió ${addressIndex}`
    );
  }
}

/** Cuenta derivada: solo datos NO secretos (HU-06-02 RN-6). */
export interface DerivedAccount {
  addressIndex: number;
  /** Dirección Ethereum con checksum EIP-55. */
  address: string;
  /** Path BIP-44 efectivamente usado. */
  derivationPath: string;
  /** Clave pública comprimida (33 bytes) en hex con prefijo `0x`. Dato NO secreto. */
  publicKey: string;
}

/** Construye el resultado público a partir del nodo hijo (la clave privada no sale de aquí). */
function toDerivedAccount(child: ExtendedKey, addressIndex: number): DerivedAccount {
  // RN-4: dirección = últimos 20 bytes de Keccak-256(X || Y) con la pública SIN comprimir.
  const addressBytes = keccak_256(uncompressedXY(child.k)).subarray(12);
  return {
    addressIndex,
    address: toChecksumAddress(addressBytes),
    derivationPath: derivationPathFor(addressIndex),
    publicKey: '0x' + bytesToHex(compressedPublicKey(child.k)),
  };
}

/**
 * Deriva la cuenta del `address_index` dado sobre `m/44'/60'/0'/0/<addressIndex>`.
 *
 * Función pura de `(seed, addressIndex)` (HU-06-02 RN-5). Valida el rango
 * `[0, 2^31 - 1]` ANTES de derivar (RN-9 => `AddressIndexRangeError`). Nunca expone ni
 * logea la clave privada (RN-6).
 *
 * Si ese índice concreto cae en el borde de BIP-32 (`I_L >= n` o `k_hijo == 0`, RN-8) lanza
 * `DerivationExhaustedError`; para avanzar automáticamente al índice siguiente usar
 * `deriveAccountFromIndexOrNext`.
 */
export function deriveAccount(
  seed: Uint8Array,
  addressIndex: number,
  deps?: DerivationDeps
): DerivedAccount {
  assertAddressIndexInRange(addressIndex);
  const hmacSha512 = deps?.hmacSha512;
  const parent = externalChainNode(seed, hmacSha512);
  try {
    return toDerivedAccount(ckdPriv(parent, addressIndex, hmacSha512), addressIndex);
  } catch (err) {
    if (err instanceof InvalidChildKeyError) {
      throw new DerivationExhaustedError(
        `el address_index ${addressIndex} produce una clave BIP-32 inválida (RN-8)`
      );
    }
    throw err;
  }
}

/**
 * Igual que `deriveAccount`, pero implementa el borde de BIP-32 de HU-06-02 RN-8: si el
 * índice produce una clave inválida (`I_L >= n` o `k_hijo == 0`), avanza determinísticamente
 * al índice siguiente hasta hallar uno válido. Si se supera `MAX_ADDRESS_INDEX` lanza
 * `DerivationExhaustedError`.
 *
 * El índice efectivamente usado se devuelve en `addressIndex` (y queda reflejado en
 * `derivationPath`), consistente con HU-06-03 RN-1.
 */
export function deriveAccountFromIndexOrNext(
  seed: Uint8Array,
  startIndex: number,
  deps?: DerivationDeps
): DerivedAccount {
  assertAddressIndexInRange(startIndex);
  const hmacSha512 = deps?.hmacSha512;
  const parent = externalChainNode(seed, hmacSha512);

  for (let index = startIndex; index <= MAX_ADDRESS_INDEX; index++) {
    try {
      return toDerivedAccount(ckdPriv(parent, index, hmacSha512), index);
    } catch (err) {
      if (err instanceof InvalidChildKeyError) continue; // RN-8: avanzar al siguiente índice
      throw err;
    }
  }

  throw new DerivationExhaustedError(
    `no se halló un address_index válido en [${startIndex}, ${MAX_ADDRESS_INDEX}]`
  );
}

