  9	import { isValidChecksumAddress, toChecksumAddress } from '../wallet/hd';
 10	
 11	/** Red única del proyecto: Sepolia (spec/00-fundaciones/activos-y-par-de-trading.md §1). */
 12	export const CHAIN_ID = '11155111';
 13	export const NETWORK_NAME = 'sepolia';
 14	/** Confirmaciones requeridas (constante fundacional; la consumen las épicas 07/08). */
 15	export const CONFIRMACIONES_REQUERIDAS = 12;
 16	
 17	export class ConfigError extends Error {}
 18	
 19	export interface RateLimitPolicy {
 20	  enabled: boolean;
 21	  max: number;
 22	  windowSeconds: number;
 23	}
