160	  const windowSeconds = declaredWindow
161	    ? parseIntStrict(rawWindow as string, windowVar)
162	    : defaults.windowSeconds;
163	  if (max <= 0) throw new ConfigError(`${maxVar} debe ser un entero positivo.`);
164	  if (windowSeconds <= 0) throw new ConfigError(`${windowVar} debe ser un entero positivo.`);
