207	  if (raw === undefined || raw.trim() === '') return [];
208	  const origins: string[] = [];
209	  for (const part of raw.split(',')) {
210	    const value = part.trim().replace(/\/$/, '');
211	    if (value === '') continue;
212	    if (value === '*') {
213	      throw new ConfigError(
214	        'CORS_ALLOWED_ORIGINS no admite el comodín "*": hay que listar orígenes exactos.',
215	      );
216	    }
217	    let url: URL;
218	    try {
219	      url = new URL(value);
220	    } catch {
221	      throw new ConfigError(
222	        `CORS_ALLOWED_ORIGINS debe listar orígenes con la forma "esquema://host[:puerto]"; ` +
223	          `se recibió "${value}".`,
224	      );
225	    }
226	    const wellFormed =
227	      (url.protocol === 'http:' || url.protocol === 'https:') &&
228	      url.username === '' &&
229	      url.password === '' &&
230	      url.search === '' &&
231	      url.hash === '' &&
232	      (url.pathname === '' || url.pathname === '/') &&
233	      url.origin === value;
234	    if (!wellFormed) {
235	      throw new ConfigError(
236	        `CORS_ALLOWED_ORIGINS debe listar orígenes exactos "esquema://host[:puerto]" (http o ` +
237	          `https, sin path, query, fragmento ni credenciales); se recibió "${value}".`,
238	      );
239	    }
240	    if (!origins.includes(url.origin)) origins.push(url.origin);
241	  }
242	  return origins;
243	}
