188	  if (hasMixedCase && !isValidChecksumAddress(value)) {
189	    throw new ConfigError(
190	      `${name} tiene caja mixta pero su checksum EIP-55 no verifica; ` +
191	        `la forma correcta de esa dirección es ${toChecksumAddress(value)}.`,
192	    );
193	  }
194	  return toChecksumAddress(value);
195	}
196	
197	/**
198	 * Parsea `CORS_ALLOWED_ORIGINS`: lista separada por comas de orígenes **exactos**
199	 * (`esquema://host[:puerto]`), p. ej. `http://localhost:5173,http://127.0.0.1:5173`.
200	 *
201	 * Vacía o ausente ⇒ lista vacía ⇒ CORS deshabilitado. Un origen mal formado (con path,
202	 * query, fragmento, credenciales, esquema no HTTP(S), o el comodín `*`) **impide el
203	 * arranque**, con el mismo mecanismo que el resto de las validaciones de configuración.
204	 * Se tolera una barra final (`http://host:5173/`) y se normaliza.
205	 */
206	export function parseCorsAllowedOrigins(raw: string | undefined): string[] {
207	  if (raw === undefined || raw.trim() === '') return [];
208	  const origins: string[] = [];
209	  for (const part of raw.split(',')) {
210	    const value = part.trim().replace(/\/$/, '');
211	    if (value === '') continue;
212	    if (value === '*') {
213	      throw new ConfigError(
214	        'CORS_ALLOWED_ORIGINS no admite el comodín "*": hay que listar orígenes exactos.',
215	      );
216	    }
217	    let url: URL;
218	    try {
219	      url = new URL(value);
220	    } catch {
221	      throw new ConfigError(
222	        `CORS_ALLOWED_ORIGINS debe listar orígenes con la forma "esquema://host[:puerto]"; ` +
223	          `se recibió "${value}".`,
224	      );
225	    }
226	    const wellFormed =
227	      (url.protocol === 'http:' || url.protocol === 'https:') &&
228	      url.username === '' &&
229	      url.password === '' &&
230	      url.search === '' &&
231	      url.hash === '' &&
232	      (url.pathname === '' || url.pathname === '/') &&
233	      url.origin === value;
234	    if (!wellFormed) {
235	      throw new ConfigError(
236	        `CORS_ALLOWED_ORIGINS debe listar orígenes exactos "esquema://host[:puerto]" (http o ` +
237	          `https, sin path, query, fragmento ni credenciales); se recibió "${value}".`,
238	      );
239	    }
240	    if (!origins.includes(url.origin)) origins.push(url.origin);
241	  }
242	  return origins;
243	}
244	
245	/**
246	 * Dirección por defecto del USDC-mock en Sepolia. Es un parámetro del despliegue
247	 * (spec/00-fundaciones/activos-y-par-de-trading.md §2.2): se sobreescribe con
248	 * `USDC_CONTRACT_ADDRESS`.
249	 */
250	export const DEFAULT_USDC_CONTRACT_ADDRESS = '0x1c7D4B196Cb0C7B01d743Fbc6116a902379C7238';
251	
252	export function loadConfig(env: NodeJS.ProcessEnv = process.env): Config {
253	  if (parseBool(env.LOAD_DOTENV, true)) {
254	    readEnvFile(path.resolve(process.cwd(), '.env'));
255	  }
256	
257	  const port = env.PORT ? parseIntStrict(env.PORT, 'PORT') : 3000;
258	  if (port < 0 || port > 65535) throw new ConfigError('PORT fuera de rango.');
259	
260	  const sessionTtlSeconds = env.SESSION_TTL_SECONDS
261	    ? parseIntStrict(env.SESSION_TTL_SECONDS, 'SESSION_TTL_SECONDS')
262	    : 3600;
263	  // HU-01-02 RN-3: TTL entero positivo en [60, 86400]; fuera de rango => no se arranca.
264	  if (sessionTtlSeconds < 60 || sessionTtlSeconds > 86400) {
265	    throw new ConfigError(
266	      `SESSION_TTL_SECONDS debe ser un entero en el rango [60, 86400]; se recibió ${sessionTtlSeconds}.`,
267	    );
268	  }
269	
270	  const chainIdEnv = (env.CHAIN_ID ?? CHAIN_ID).trim();
271	  if (chainIdEnv !== CHAIN_ID) {
272	    throw new ConfigError(
273	      `La única red soportada es Sepolia (chainId ${CHAIN_ID}); se configuró ${chainIdEnv}.`,
274	    );
275	  }
276	
277	  return {
278	    host: env.HOST?.trim() || '0.0.0.0',
279	    port,
280	    databasePath: env.DATABASE_PATH?.trim() || path.resolve(process.cwd(), 'data', 'exchange.db'),
281	    sessionTtlSeconds,
282	    walletEncryptionKeyRaw: env.WALLET_ENCRYPTION_KEY,
283	    walletMnemonic: env.WALLET_MNEMONIC?.trim() ? env.WALLET_MNEMONIC.trim() : undefined,
284	    walletMnemonicPassphrase: env.WALLET_MNEMONIC_PASSPHRASE ?? '',
285	    usdcContractAddress: normalizeContractAddress(
286	      env.USDC_CONTRACT_ADDRESS?.trim() || DEFAULT_USDC_CONTRACT_ADDRESS,
287	      'USDC_CONTRACT_ADDRESS',
288	    ),
289	    ethRpcUrl: env.ETH_RPC_URL?.trim() || '',
290	    apiRateLimit: rateLimitFrom(
291	      env,
292	      'API_RATE_LIMIT_ENABLED',
293	      'API_RATE_LIMIT_MAX',
294	      'API_RATE_LIMIT_WINDOW_SECONDS',
295	      // HU-09-02 RN-12: 60 requests por minuto, por cuenta y por endpoint.
296	      { enabled: true, max: 60, windowSeconds: 60 },
297	      false,
298	    ),
299	    registerRateLimit: rateLimitFrom(
300	      env,
301	      'REGISTER_RATE_LIMIT_ENABLED',
302	      'REGISTER_RATE_LIMIT_MAX',
303	      'REGISTER_RATE_LIMIT_WINDOW_SECONDS',
304	      // HU-01-01 RN-10: opcional; desactivado salvo configuración explícita del entorno.
305	      { enabled: false, max: 20, windowSeconds: 60 },
306	      true,
307	    ),
308	    loginRateLimit: rateLimitFrom(
309	      env,
310	      'LOGIN_RATE_LIMIT_ENABLED',
311	      'LOGIN_RATE_LIMIT_MAX_FAILURES',
312	      'LOGIN_RATE_LIMIT_WINDOW_SECONDS',
313	      // HU-01-02 RN-9: opcional; cuenta intentos fallidos por (origen, email).
314	      { enabled: false, max: 5, windowSeconds: 60 },
315	      true,
316	    ),
317	    internalApiToken: env.INTERNAL_API_TOKEN?.trim() || undefined,
318	    corsAllowedOrigins: parseCorsAllowedOrigins(env.CORS_ALLOWED_ORIGINS),
319	    logLevel: env.LOG_LEVEL?.trim() || 'info',
320	  };
321	}

