     1	/**
     2	 * Persistencia (INV-8). Se usa SQLite a través del módulo estándar `node:sqlite`, de modo
     3	 * que no hace falta compilar dependencias nativas ni levantar un servidor de base de datos.
     4	 *
     5	 * Todas las escrituras que deben ser atómicas se ejecutan dentro de una transacción
     6	 * (`transaction()`), y `node:sqlite` es síncrono: una transacción se ejecuta completa en un
     7	 * único tick del event loop, por lo que ninguna otra request puede intercalarse.
     8	 */
     9	import { DatabaseSync } from 'node:sqlite';
    10	import * as fs from 'node:fs';
    11	import * as path from 'node:path';
    12	
    13	export type Db = DatabaseSync;
    14	
    15	const SCHEMA = `
    16	CREATE TABLE IF NOT EXISTS accounts (
    17	  account_id    TEXT PRIMARY KEY,
    18	  email         TEXT NOT NULL UNIQUE,
    19	  password_hash TEXT NOT NULL,
    20	  status        TEXT NOT NULL,
    21	  created_at    TEXT NOT NULL
    22	);
    23	
    24	-- Estado inicial de balances de una cuenta (HU-01-01 RN-6 / RNE-6): disponible y bloqueado
    25	-- en "0" para ETH y USDC. El modelo de balances y su superficie de API son de la épica 02
    26	-- (fuera del alcance de esta etapa); aquí sólo se materializa el estado inicial.
    27	CREATE TABLE IF NOT EXISTS account_balances (
    28	  account_id TEXT NOT NULL REFERENCES accounts(account_id),
    29	  asset      TEXT NOT NULL,
    30	  available  TEXT NOT NULL DEFAULT '0',
    31	  locked     TEXT NOT NULL DEFAULT '0',
    32	  PRIMARY KEY (account_id, asset)
    33	);
    34	
    35	CREATE TABLE IF NOT EXISTS sessions (
    36	  token_hash TEXT PRIMARY KEY,
    37	  account_id TEXT NOT NULL REFERENCES accounts(account_id),
    38	  created_at TEXT NOT NULL,
    39	  expires_at TEXT NOT NULL,
    40	  revoked_at TEXT
    41	);
    42	CREATE INDEX IF NOT EXISTS idx_sessions_account ON sessions(account_id);
    43	
    44	-- Seed HD cifrado en reposo con AES-256-GCM: nonce(12) || ciphertext || tag(16).
    45	CREATE TABLE IF NOT EXISTS wallet_seed (
    46	  id         INTEGER PRIMARY KEY CHECK (id = 1),
    47	  payload    BLOB NOT NULL,
    48	  created_at TEXT NOT NULL
    49	);
    50	
    51	CREATE TABLE IF NOT EXISTS deposit_addresses (
    52	  account_id      TEXT PRIMARY KEY REFERENCES accounts(account_id),
    53	  address_index   INTEGER NOT NULL UNIQUE,
    54	  address         TEXT NOT NULL UNIQUE,
    55	  derivation_path TEXT NOT NULL,
    56	  network         TEXT NOT NULL,
    57	  chain_id        TEXT NOT NULL,
    58	  created_at      TEXT NOT NULL
    59	);
    60	
    61	-- Auditoría de índices BIP-32 saltados por clave inválida (HU-06-02 RN-8 / HU-06-03 RN-1).
    62	CREATE TABLE IF NOT EXISTS derivation_skips (
    63	  address_index INTEGER PRIMARY KEY,
    64	  reason        TEXT NOT NULL,
    65	  created_at    TEXT NOT NULL
    66	);
    67	
    68	-- Eventos de dominio internos (HU-06-03 RN-11: DepositAddressAssigned).
    69	CREATE TABLE IF NOT EXISTS domain_events (
    70	  id         INTEGER PRIMARY KEY AUTOINCREMENT,
    71	  type       TEXT NOT NULL,
    72	  payload    TEXT NOT NULL,
    73	  created_at TEXT NOT NULL
    74	);
    75	
    76	-- Log de auditoría interno de autenticación (RNE-9). No es consultable por el usuario final.
    77	CREATE TABLE IF NOT EXISTS auth_audit_log (
    78	  id         INTEGER PRIMARY KEY AUTOINCREMENT,
    79	  timestamp  TEXT NOT NULL,
    80	  event      TEXT NOT NULL,
    81	  email      TEXT,
    82	  result     TEXT NOT NULL,
    83	  reason     TEXT,
    84	  origin     TEXT
    85	);
    86	`;
    87	
    88	export function openDatabase(databasePath: string): Db {
    89	  if (databasePath !== ':memory:') {
    90	    fs.mkdirSync(path.dirname(path.resolve(databasePath)), { recursive: true });
    91	  }
    92	  const db = new DatabaseSync(databasePath);
    93	  db.exec('PRAGMA journal_mode = WAL');
    94	  db.exec('PRAGMA synchronous = FULL');
    95	  db.exec('PRAGMA foreign_keys = ON');
    96	  db.exec('PRAGMA busy_timeout = 5000');
    97	  db.exec(SCHEMA);
    98	  return db;
    99	}
   100	
   101	/** Ejecuta `fn` dentro de una transacción; revierte por completo ante cualquier excepción. */
   102	export function transaction<T>(db: Db, fn: () => T): T {
   103	  db.exec('BEGIN IMMEDIATE');
   104	  try {
   105	    const result = fn();
   106	    db.exec('COMMIT');
   107	    return result;
   108	  } catch (err) {
   109	    try {
   110	      db.exec('ROLLBACK');
   111	    } catch {
   112	      /* la transacción ya no estaba abierta */
   113	    }
   114	    throw err;
   115	  }
   116	}
   117	
   118	export function isUniqueConstraintError(err: unknown): boolean {
   119	  const message = err instanceof Error ? err.message : String(err);
   120	  return /UNIQUE constraint failed/i.test(message);
   121	}

