/**
 * Superficie HTTP de la API (épica 09, alcance de esta etapa).
 *
 * Contrato: ruta base `/api/v1`, envelope uniforme de error
 * `{ error: { code, message, details? } }`, un solo error por respuesta según la
 * precedencia determinista, y autenticación por token Bearer en los recursos protegidos.
 */
import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from 'fastify';
import { AppError, validationError } from '../core/errors';
import { CHAIN_ID, NETWORK_NAME, type Config } from '../core/config';
import { nowIso } from '../core/time';
import { normalizeEmail } from '../core/validation';
import type { Db } from '../db/index';
import type { AuditLog } from '../core/audit';
import type { AccountService } from '../modules/accounts/service';
import type { SessionService } from '../modules/accounts/sessions';
import type { WalletService } from '../modules/wallet/service';
import { SlidingWindowLimiter } from './rateLimit';

export interface AppDependencies {
  config: Config;
  db: Db;
  accounts: AccountService;
  sessions: SessionService;
  wallet: WalletService;
  audit: AuditLog;
}

/** Verbos soportados por cada ruta existente (para responder 405 y no 404). */
const ROUTE_METHODS: Record<string, string[]> = {
  '/health': ['GET', 'HEAD'],
  '/api/v1/auth/register': ['POST'],
  '/api/v1/auth/login': ['POST'],
  '/api/v1/me': ['GET', 'HEAD'],
  '/api/v1/deposit-address': ['GET', 'HEAD'],
  '/internal/deposit-addresses': ['GET', 'HEAD'],
};

const SUPPORTED_ASSETS = ['ETH', 'USDC'] as const;
type SupportedAsset = (typeof SUPPORTED_ASSETS)[number];

function normalizePath(url: string): string {
  const pathname = url.split('?')[0];
  if (pathname.length > 1 && pathname.endsWith('/')) return pathname.slice(0, -1);
  return pathname;
}

/**
 * Error de parseo del cuerpo diferido hasta después del paso 0 de la precedencia
 * (rate limiting) y de la autenticación. Se guarda en la request bajo un símbolo propio.
 */
const DEFERRED_BODY_ERROR = Symbol('deferredBodyError');

type RequestWithDeferredError = { [DEFERRED_BODY_ERROR]?: AppError };

function deferBodyError(request: unknown, error: AppError): void {
  (request as RequestWithDeferredError)[DEFERRED_BODY_ERROR] = error;
}

/** Levanta el error de parseo diferido, si lo hubo. */
...
  // ---------------------------------------------------------------------------
  // Health check
  // ---------------------------------------------------------------------------
  app.get('/health', async () => ({
    status: 'ok',
    service: 'cex-backend',
    time: nowIso(),
    network: NETWORK_NAME,
    chainId: CHAIN_ID,
    rpcConfigured: config.ethRpcUrl !== '',
  }));

  // ---------------------------------------------------------------------------
  // HU-01-01 — Registro (público, 201)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/register', async (request, reply) => {
    // Paso 0 de la precedencia (HU-01-01 RN-9/RN-10): rate limiting antes de todo.
    const decision = registerLimiter.consume(`${request.ip}`);
    if (decision.limited) {
      throw new AppError(
        'RATE_LIMITED',
        'Se superó el límite de registros permitido desde este origen.',
        { retryAfterSeconds: decision.retryAfterSeconds },
        { 'Retry-After': String(decision.retryAfterSeconds) },
      );
    }
    // Paso 1 en adelante: recién ahora se reporta un cuerpo que no parsea (RN-9).
    throwDeferredBodyError(request);
    const account = await accounts.register(request.body, request.ip ?? null);
    return reply.status(201).send(account);
  });

  // ---------------------------------------------------------------------------
  // HU-01-02 — Login (público, 200)
  // ---------------------------------------------------------------------------
  app.post('/api/v1/auth/login', async (request, reply) => {
    // Paso 0: rate limiting de intentos fallidos por (origen, email), uniforme y sin
    // revelar la existencia del email (HU-01-02 RN-8/RN-9).
    const rawEmail =
      typeof request.body === 'object' &&
      request.body !== null &&
      typeof (request.body as Record<string, unknown>).email === 'string'
        ? normalizeEmail((request.body as Record<string, string>).email)
        : '';
    const limiterKey = `${request.ip}|${rawEmail}`;
    // Si el cuerpo no parseó no hay email: el paso 0 se evalúa igual, con el origen como
    // granularidad, para que una solicitud con payload inválido responda 429 y no 422
    // (HU-01-02 RN-8).
    const decision =
      rawEmail === ''
