test('AT-06-02-08: I_L >= n en un índice => se avanza determinísticamente al índice siguiente', () => {
  const INDICE_ROTO = 5;
  // I forjado: I_L = n (>= n, condición inválida de BIP-32 RN-8), I_R arbitrario.
  const I_FORZADO = Buffer.concat([Buffer.from(ser256(SECP256K1_N)), Buffer.alloc(32, 0xab)]);

  let intercepciones = 0;
  const deps: DerivationDeps = {
    hmacSha512: (key, data) => {
      // Solo el último paso (derivación normal de 33+4 bytes) del índice objetivo.
      if (data.length === 37 && endsWithIndex(data, INDICE_ROTO)) {
        intercepciones++;
        return new Uint8Array(I_FORZADO);
      }
      return hmac(sha512, key, data);
    },
  };

  const derivada = deriveAccountFromIndexOrNext(seedHardhat, INDICE_ROTO, deps);

  assert.equal(intercepciones, 1, 'la inyección se activó exactamente en el índice roto');
  assert.equal(derivada.addressIndex, INDICE_ROTO + 1, 'se avanzó al índice siguiente (RN-8)');
  assert.equal(derivada.derivationPath, `m/44'/60'/0'/0/${INDICE_ROTO + 1}`);

  // El resultado es exactamente el del índice siguiente derivado normalmente, y determinista.
  const esperado = deriveAccount(seedHardhat, INDICE_ROTO + 1);
  assert.deepEqual(derivada, esperado);
  assert.deepEqual(deriveAccountFromIndexOrNext(seedHardhat, INDICE_ROTO, deps), derivada);

  // Sin inyección, el índice roto deriva normalmente (la condición no ocurre en la realidad).
  assert.equal(deriveAccountFromIndexOrNext(seedHardhat, INDICE_ROTO).addressIndex, INDICE_ROTO);

  // La variante estricta señala el borde en lugar de saltarlo.
  assert.throws(
    () => deriveAccount(seedHardhat, INDICE_ROTO, deps),
    DerivationExhaustedError
  );
});

