test('AT-06-03-08: cuenta inexistente ⇒ ACCOUNT_NOT_FOUND (404) con details.accountId', async () => {
  const ctx = createTestApp();
  try {
    await registerAccount(ctx.app, uniqueEmail()); // una cuenta real, para tener estado
    const filasAntes = addressRows(ctx.db);
    const inexistente = '00000000-0000-4000-8000-000000000000';

    const error = capturarError(() => ctx.services.wallet.getOrAssign(inexistente));
    assert.ok(error instanceof AppError, `se esperaba AppError, llegó: ${String(error)}`);
    assert.equal(error.code, 'ACCOUNT_NOT_FOUND');
    assert.equal(error.httpStatus, 404);
    assert.deepEqual(error.details, { accountId: inexistente });

    // No se asignó ningún índice ni se derivó ninguna dirección.
    assert.deepEqual(addressRows(ctx.db), filasAntes);
    assert.equal(ctx.services.wallet.find(inexistente), undefined);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-03-09: asignación eager — la dirección existe inmediatamente después del alta', async () => {
  const ctx = createTestApp();
  try {
    const cuenta = await registerAccount(ctx.app, uniqueEmail());
    // Sin ninguna consulta previa del usuario, el registro ya está persistido.
    const fila = ctx.db
      .prepare(
        `SELECT account_id AS accountId, address_index AS addressIndex, address,
                derivation_path AS derivationPath, network, chain_id AS chainId
         FROM deposit_addresses WHERE account_id = ?`,
      )
      .get(cuenta.accountId) as unknown as AddressRow | undefined;
    assert.ok(fila, 'el alta no asignó la dirección de forma eager');
    assert.equal(fila.accountId, cuenta.accountId);
    assert.ok(Number.isInteger(fila.addressIndex));
    assert.ok(isEip55(fila.address));
    assert.equal(fila.derivationPath, `m/44'/60'/0'/0/${fila.addressIndex}`);
    assert.equal(fila.network, NETWORK);
    assert.equal(fila.chainId, CHAIN_ID);
  } finally {
    await ctx.cleanup();
  }
});

test('AT-06-03-10: se emite el evento DepositAddressAssigned y la dirección es consultable internamente', async () => {
  const ctx = createTestApp();
  try {
    const recibidos: Record<string, unknown>[] = [];
    ctx.services.wallet.events.on(DEPOSIT_ADDRESS_ASSIGNED, (evento) => {
      recibidos.push(evento as Record<string, unknown>);
    });

    const cuenta = await registerAccount(ctx.app, uniqueEmail());
    const registro = ctx.services.wallet.find(cuenta.accountId);
